using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Net;
using System.Text;
using System.Threading;
using System.Windows.Forms;
namespace Astera {
// Public store header fallback when Steam has not cached library artwork locally.
static class SteamPublicArtwork {
    sealed class Reply {public bool success {get;set;}public Data data {get;set;}}
    sealed class Data {public string header_image {get;set;}}
    internal static bool Address(string value){Uri u;return Uri.TryCreate(value,UriKind.Absolute,out u)&&u.Scheme=="https"&&u.IsDefaultPort&&String.IsNullOrEmpty(u.UserInfo)&&String.IsNullOrEmpty(u.Fragment)&&AllowedHost(u.Host);}
    static bool AllowedHost(string host){return host=="shared.akamai.steamstatic.com"||host=="shared.fastly.steamstatic.com"||host=="cdn.akamai.steamstatic.com"||host=="cdn.fastly.steamstatic.com";}
    internal static string Header(string id,byte[] json){if(!PlatformLibraries.Id(id)||json.Length>1024*1024)throw new IOException("Invalid Steam artwork metadata");var replies=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=1024*1024}.Deserialize<Dictionary<string,Reply>>(Encoding.UTF8.GetString(json));Reply reply;return replies!=null&&replies.TryGetValue(id,out reply)&&reply!=null&&reply.success&&reply.data!=null&&Address(reply.data.header_image)?reply.data.header_image:null;}
    internal static string CachePath(string root,string id){if(!PlatformLibraries.Id(id))throw new IOException("Invalid Steam app ID");return Path.Combine(root,id+"-background.png");}
    internal static string Optional(Func<string> resolve,CancellationToken cancel){try{cancel.ThrowIfCancellationRequested();return resolve();}catch(OperationCanceledException){throw;}catch(WebException){cancel.ThrowIfCancellationRequested();return null;}catch(IOException){return null;}catch(ArgumentException){return null;}catch(UnauthorizedAccessException){return null;}}
    internal static string Resolve(string id,string root,CancellationToken cancel){return ResolveKind(id,root,false,cancel);}
    internal static string ResolvePortrait(string id,string root,CancellationToken cancel){return ResolveKind(id,root,true,cancel);}
    static string ResolveKind(string id,string root,bool portrait,CancellationToken cancel){cancel.ThrowIfCancellationRequested();string path=portrait?Path.Combine(root,id+"-portrait.png"):CachePath(root,id);if(!PlatformLibraries.Id(id))throw new IOException("Invalid Steam app ID");if(File.Exists(path))try{using(var image=Banner.ReadArtwork(path)){}return path;}catch(IOException){}catch(ArgumentException){}
        byte[] bytes;try{bytes=Download("https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/"+id+(portrait?"/library_600x900.jpg":"/library_hero.jpg"),cancel);}catch(WebException error){var response=error.Response as HttpWebResponse;if(response==null||response.StatusCode!=HttpStatusCode.NotFound)throw;response.Dispose();byte[] metadata;using(var output=new MemoryStream()){new Transport().Get("https://store.steampowered.com/api/appdetails?appids="+id+"&filters=basic",output,1024*1024,-1,cancel,null);metadata=output.ToArray();}string url=Header(id,metadata);if(url==null)return null;bytes=Download(url,cancel);}Directory.CreateDirectory(root);string temp=path+"."+Guid.NewGuid().ToString("N")+".partial";
        try{using(var input=new MemoryStream(bytes))using(var image=Image.FromStream(input,true,true)){if(image.Width<32||image.Height<16||image.Width>4096||image.Height>4096)throw new IOException("Unsupported Steam image dimensions");double scale=Math.Min(1,1600D/Math.Max(image.Width,image.Height));using(var bitmap=new Bitmap(Math.Max(1,(int)(image.Width*scale)),Math.Max(1,(int)(image.Height*scale)))){using(var g=Graphics.FromImage(bitmap))g.DrawImage(image,0,0,bitmap.Width,bitmap.Height);bitmap.Save(temp,ImageFormat.Png);}}cancel.ThrowIfCancellationRequested();if(new FileInfo(temp).Length>8*1024*1024)throw new IOException("Decoded Steam image too large");SteamArtworkCache.Trim(root,path,new FileInfo(temp).Length);if(File.Exists(path))File.Delete(path);File.Move(temp,path);return path;}finally{if(File.Exists(temp))File.Delete(temp);}
    }
    static byte[] Download(string address,CancellationToken cancel){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var uri=new Uri(address);for(int i=0;i<5;i++){if(!Address(uri.AbsoluteUri))throw new IOException("Untrusted Steam artwork address");cancel.ThrowIfCancellationRequested();var request=(HttpWebRequest)WebRequest.Create(uri);request.AllowAutoRedirect=false;request.Timeout=request.ReadWriteTimeout=15000;request.UserAgent="Astera/0.1";using(cancel.Register(delegate{request.Abort();}))using(var response=(HttpWebResponse)request.GetResponse()){int code=(int)response.StatusCode;if(code>=300&&code<400){uri=new Uri(uri,response.Headers["Location"]);continue;}if(code!=200||response.ContentLength>8*1024*1024)throw new IOException("Unexpected Steam image response");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var buffer=new byte[16384];int n;while((n=input.Read(buffer,0,buffer.Length))>0){cancel.ThrowIfCancellationRequested();if(output.Length+n>8*1024*1024)throw new IOException("Steam image too large");output.Write(buffer,0,n);}return output.ToArray();}}}throw new IOException("Too many Steam image redirects");}
}
sealed partial class LibraryForm {
    internal static int AuditPublicSteamArtwork(string root,string id){try{if(Directory.Exists(root))throw new IOException("Use a new artwork check folder");Directory.CreateDirectory(root);string image=SteamPublicArtwork.Resolve(id,Path.Combine(root,"cache"),CancellationToken.None);if(String.IsNullOrEmpty(image))throw new IOException("Steam did not provide a header image");string portrait=SteamPublicArtwork.ResolvePortrait(id,Path.Combine(root,"cache"),CancellationToken.None);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var state=new Store(Path.Combine(root,"state"));state.Settings.CheckOnStart=false;state.Settings.UseMinecraftSkin=false;state.Settings.KeepInTray=false;var game=new CustomGame{Name="PEAK",Executable=Path.Combine(root,"PEAK.exe")};File.WriteAllText(game.Executable,"Artwork fixture only; not executed");for(int i=0;i<30;i++)state.Settings.CustomGames.Add(new CustomGame{Name="Example library game "+i,Executable=game.Executable});state.Settings.CustomGames.Add(game);using(var form=new LibraryForm(state,new Channel(),true))using(var timer=new System.Windows.Forms.Timer{Interval=800}){form.StartPosition=FormStartPosition.Manual;form.Location=Screen.PrimaryScreen.WorkingArea.Location;form.TopMost=true;form.ApplySteamArtwork(game.Executable,new SteamGameArt{AppId=id,Name="PEAK",Hero=image,Icon=portrait});form.ReloadGames(game);form.SelectLibraryTab(0);int result=1;timer.Tick+=delegate{timer.Stop();try{form.CaptureVisibleUi(root,"steam-public-artwork");File.WriteAllText(Path.Combine(root,"result.json"),MC2Pack.Engine.Json.Serialize(new{Passed=true,AppId=id,CachedImage=image,GamesExecuted=false,LivePreferencesChanged=false}));result=0;}catch(Exception error){File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());}form.Close();};form.Shown+=delegate{timer.Start();};Application.Run(form);return result;}}catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
